def update_product(id: int, product: ProductSchema, db: Session = Depends(get_db)):
    db_product = db.query(Product).filter(Product.id == id).first()
    if not db_product: raise HTTPException(status_code=404, detail="Not found")
    for key, value in product.dict().items(): setattr(db_product, key, value)
    db.commit()
    return db_product

@app.delete("/products/{id}")
def delete_product(id: int, db: Session = Depends(get_db)):
    db_product = db.query(Product).filter(Product.id == id).first()
    if not db_product: raise HTTPException(status_code=404, detail="Not found")
    db.delete(db_product)
    db.commit()
    return {"ok": True}
