  body('username').isAlphanumeric().isLength({ min: 3, max: 30 }).trim().escape(),
  body('email').isEmail().normalizeEmail()
], async (req, res) => {

  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  try {
    const user = new User(req.body);
    await user.save();
    res.status(201).json(user);
  } catch (err) {
    res.status(500).json({ message: 'Erro interno ao salvar usuário' });
  }
});

// Rota de Leitura
app.get('/users/:id', async (req, res) => {
  try {
    // Validação básica de ID para prevenir casts maliciosos
    if (!mongoose.Types.ObjectId.isValid(req.params.id)) {
      return res.status(400).json({ message: 'ID inválido' });
    }

    const user = await User.findById(req.params.id);
    if (!user) return res.status(404).json({ message: 'Usuário não encontrado' });
    res.json(user);
  } catch (err) {
    res.status(500).json({ message: 'Erro ao buscar usuário' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Servidor seguro rodando na porta ${PORT}`));
```

