```

### Código do Middleware (`gateway.js`)

```javascript
const express = require('express');
const dicomParser = require('dicom-parser');
const sharp = require('sharp');
const axios = require('axios');

const app = express();
app.use(express.raw({ type: 'application/dicom', limit: '50mb' }));

/**
 * Middleware de Transcodificação Acelerada
 * Converte DICOM para formato proprietário (Ex: WebP/Lossless via Sharp)
 */
app.post('/gateway/dicom-to-legacy', async (req, res) => {
    try {
        const dicomBuffer = req.body;

        // 1. Parsing seguro do DataSet DICOM
        const dataSet = dicomParser.parseDicom(dicomBuffer);

        // 2. Extração do Pixel Data (Exemplo simplificado)
        // Em produção, utilize o 'pixelData' extraído do DataSet
        const pixelData = dataSet.byteArray.slice(dataSet.pixelDataOffset);

        // 3. Transcodificação Acelerada via GPU (Sharp)
        // Sharp utiliza libvips com suporte a aceleração via hardware quando configurado
        const processedImage = await sharp(Buffer.from(pixelData), {
            raw: {
                width: dataSet.uint16('x00280011'), // Columns
                height: dataSet.uint16('x00280010'), // Rows
                channels: 1 
            }
        })
        .toFormat('webp') // Formato proprietário de destino
        .toBuffer();

        // 4. Encaminhamento para Sistema Legado
        const response = await axios.post('http://legacy-system.internal/api/import', processedImage, {
            headers: { 'Content-Type': 'image/webp' }
        });

        res.status(200).json({ status: 'success', legacyId: response.data.id });

    } catch (error) {
        console.error('Security/Processing Error:', error.message);
        res.status(500).send('Internal Processing Error');
    }
});

app.listen(3000, () => console.log('Secure DICOM Gateway running on port 3000'));
```

### Considerações de Segurança (Cyber Defense):

