```javascript
const CACHE_NAME = 'pwa-cache-v1';
const DYNAMIC_CACHE = 'dynamic-cache-v1';
const ASSETS = [
  '/',
  '/index.html',
  '/styles.css',
  '/script.js',
  '/offline.html'
];

// Instalação: Cache estático
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS))
  );
});

// Ativação: Limpeza de caches antigos
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(
      keys.filter((key) => key !== CACHE_NAME && key !== DYNAMIC_CACHE)
          .map((key) => caches.delete(key))
    ))
  );
});

// Fetch: Estratégia Cache-First com fallback dinâmico
self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request).then((cachedResponse) => {
      return cachedResponse || fetch(event.request).then((response) => {
        return caches.open(DYNAMIC_CACHE).then((cache) => {
          cache.put(event.request, response.clone());
          return response;
        });
      });
    }).catch(() => caches.match('/offline.html'))
  );
});

// Push Notifications
self.addEventListener('push', (event) => {
  const data = event.data ? event.data.json() : { title: 'Nova Notificação', body: 'Você tem uma nova mensagem!' };

  const options = {
    body: data.body,
    icon: '/icon.png',
    badge: '/badge.png'
  };

  event.waitUntil(
    self.registration.showNotification(data.title, options)
  );
});

// Clique na Notificação
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil(clients.openWindow('/'));
});
```

Para implementar um Service Worker seguro e eficiente, utilizaremos a biblioteca oficial **`workbox-sw`**, que é o padrão industrial para gerenciamento de cache e estratégias offline em PWAs.

### Pré-requisitos
Instale a dependência via npm:
`npm install workbox-window`

### Implementação do Service Worker (`sw.js`)

Este código segue as melhores práticas de segurança: utiliza escopo restrito, validação de origem e estratégias de cache resilientes.

```javascript
import { precacheAndRoute } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { NetworkFirst, CacheFirst, StaleWhileRevalidate } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';

// 1. Precache de assets críticos (gerado pelo build tool, ex: Webpack/Vite)
precacheAndRoute(self.__WB_MANIFEST || []);

// 2. Cache Dinâmico para Imagens (CacheFirst)
registerRoute(
  ({ request }) => request.destination === 'image',
  new CacheFirst({
    cacheName: 'images-cache',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 dias
      }),
    ],
  })
);

// 3. Cache Dinâmico para API/JSON (NetworkFirst para dados frescos)
registerRoute(
  ({ url }) => url.pathname.startsWith('/api/'),
  new NetworkFirst({
    cacheName: 'api-cache',
  })
);

// 4. Manipulação de Web Push Notifications
self.addEventListener('push', (event) => {
  if (!(self.Notification && self.Notification.permission === 'granted')) {
    return;
  }

  const data = event.data?.json() ?? { title: 'Notificação', body: 'Nova atualização!' };

  event.waitUntil(
    self.registration.showNotification(data.title, {
      body: data.body,
      icon: '/icon-192x192.png',
      badge: '/badge-72x72.png',
      data: { url: data.url || '/' }
    })
  );
});

// 5. Clique na notificação (Segurança: redirecionamento via URL absoluta)
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil(
    self.clients.openWindow(event.notification.data.url)
  );
});
```

### Registro no Cliente (`main.js`)

```javascript
import { Workbox } from 'workbox-window';

if ('serviceWorker' in navigator) {
  const wb = new Workbox('/sw.js');

  wb.register();

  // Solicitar permissão de Push de forma segura
  async function requestPushPermission() {
    const permission = await Notification.requestPermission();
    if (permission === 'granted') {
      console.log('Permissão de notificações concedida.');
    }
  }
}
```

### Considerações de Segurança (Cyber Defense):
1.  **Integridade (SRI):** Ao servir o arquivo `sw.js`, garanta que seu servidor envie o header `Service-Worker-Allowed` corretamente configurado.
2.  **HTTPS Obrigatório:** Service Workers só operam em contextos seguros (TLS).
3

