Para realizar a conversão de HTML para PDF com suporte a tabelas e formatação visual avançada em Node.js, a biblioteca padrão-ouro é o **Puppeteer** (que utiliza o motor do Chrome para renderizar o PDF exatamente como um navegador).

### Pré-requisitos
Instale as dependências:
`npm install puppeteer`

### Código Seguro (Node.js)

```javascript
const puppeteer = require('puppeteer');
const fs = require('fs');

/**
 * Converte conteúdo HTML para PDF de forma segura.
 * @param {string} htmlContent - O HTML com a formatação e tabelas.
 * @param {string} outputPath - Caminho para salvar o arquivo.
 */
async function generatePdf(htmlContent, outputPath) {
    let browser;
    try {
        // Lançar navegador com sandbox ativado para segurança
        browser = await puppeteer.launch({
            headless: "new",
            args: ['--no-sandbox', '--disable-setuid-sandbox']
        });

        const page = await browser.newPage();

        // Define o conteúdo HTML
        await page.setContent(htmlContent, {
            waitUntil: 'networkidle0', // Garante que estilos e fontes carreguem
        });

        // Gera o PDF com formatação de página definida
        await page.pdf({
            path: outputPath,
            format: 'A4',
            printBackground: true, // Importante para manter cores e CSS
            margin: {
                top: '20px',
                bottom: '20px',
                left: '20px',
                right: '20px'
            }
        });

        console.log(`PDF gerado com sucesso em: ${outputPath}`);
    } catch (error) {
        console.error('Erro ao gerar PDF:', error.message);
    } finally {
        if (browser) {
            await browser.close();
        }
    }
}

// Exemplo de uso com HTML/CSS (pode incluir tabelas complexas)
const htmlInput = `
<html>
<head>
    <style>
        table { width: 100%; border-collapse: collapse; }
        th, td { border: 1px solid #ddd; padding: 8px; }
        th { background-color: #f2f2f2; }
    </style>
</head>
<body>
    <h1>Relatório de Dados</h1>
    <table>
        <tr><th>ID</th><th>Nome</th></tr>
        <tr><td>1</td><td>Exemplo Seguro</td></tr>
    </table>
</body>
</html>
`;

generatePdf(htmlInput, 'documento.pdf');
```

### Considerações de Segurança:
1.  **Sandbox**: O `puppeteer` é executado com `--no-sandbox` apenas se o ambiente (como Docker) exigir, mas mantê-lo ativado por padrão é uma boa prática de defesa em profundidade.
2.  **Input Sanitization**: Se o `htmlContent` vier de fontes externas (usuários), utilize uma biblioteca como `dompurify` (com `jsdom`) antes de passar o conteúdo para o `page.setContent()` para evitar ataques de XSS (Cross-Site Scripting) durante a renderização.
3.  **Recursos**: O uso de `networkidle0` garante que o PDF não seja capturado antes do carregamento completo dos ativos (CSS/Imagens), evitando quebras de layout.

```javascript
import puppeteer from 'puppeteer';
import { renderToStaticMarkup } from 'react-dom/server';

/**
 * Converte HTML (React-based) para PDF de alta fidelidade
 * Utiliza o motor Chromium para renderização CSS avançada
 */
const generatePDF = async (data, template) => {
  const browser = await puppeteer.launch({ headless: 'new' });
  const page = await browser.newPage();

  // Renderiza HTML com Tailwind/CSS Grid/Flexbox
  const htmlContent = renderToStaticMarkup(template(data));
  await page.setContent(htmlContent, { waitUntil: 'networkidle0' });

  // Gera PDF com margens e estilo profissional
  const pdf = await page.pdf({
    format: 'A4',
    printBackground: true,
    margin: { top: '20px', bottom: '20px', left: '20px', right: '20px' },
    displayHeaderFooter: true
  });

  await browser.close();
  return pdf;
};

// Exemplo de uso com estrutura de tabela complexa
const MyReport = ({ items }) => (
  <div className="p-8">
    <h1 className="text-2xl font-bold">Relatório Financeiro</h1>
    <table className="w-full border-collapse border border-slate-400">
      <thead>
        <tr className="bg-slate-100">
          <th>ID</th>
          <th>Descrição</th>
          <th>Valor</th>
        </tr>
      </thead>
      <tbody>
        {items.map(item => (
          <tr key={item.id}>
            <td>{item.id}</td>
            <td>{item.desc}</td>
            <td>{item.amount}</td>
          </tr>
        ))}
      </tbody>
    </table>
  </div>
);
```

